const $=s=>document.querySelector(s);
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const LEVELS=[
 {id:'map',title:'What an IND is for',group:0,goal:'Explain what an IND supports—and what an activity result cannot establish.',concept:'A development candidate is a molecule your team chooses to advance. An Investigational New Drug (IND) application brings together evidence supporting a specific proposed human study. It connects biological activity, exposure, potential harms, product quality, and the clinical plan.',takeaway:'The question is: does this evidence support this proposed study?',exampleTitle:'A tumor response is one piece of the argument.',example:'Suppose a candidate slows tumor growth in mice. That gives the team a reason to investigate further. Before proposing a human study, the team also needs to understand achieved exposure, potential harms, the material to be administered, and the study design.',worked:'Keep the useful activity result. Then identify the questions it leaves unanswered.',source:[0,1]},
 {id:'model',title:'What the model can tell you',group:1,goal:'Separate a measured result from an unsupported human inference.',concept:'A model is useful for the biological conditions it actually tests. A negative safety finding is more informative when the relevant tissue experienced the pharmacological perturbation. Species biology, exposure, duration, and the assessments used all affect the interpretation.',takeaway:'Ask whether the model tested the mechanism behind the risk.',exampleTitle:'Human tumor. Mouse intestine.',example:'A human tumor grows in a mouse. The drug suppresses the tumor’s XYZ1 pathway and slows growth. No intestinal injury is detected, but the mouse intestinal pathway was not suppressed. For this example, assume normal human intestine also needs XYZ1 function.',worked:'The tumor result supports activity in that model. The lack of intestinal injury does not establish that human intestine will be spared.',source:[9]},
 {id:'exposure',title:'Dose versus exposure',group:1,goal:'Explain why the same administered dose can produce different exposure.',concept:'Dose is the amount administered. Exposure describes drug concentration over time. Bioavailability is the fraction of a dose reaching systemic circulation; for an oral drug, it reflects absorption and presystemic loss. AUC—the area under a concentration–time curve—is one exposure measure.',takeaway:'Compare achieved exposure, not just the amount administered.',exampleTitle:'Same dose. More drug reaches circulation.',example:'In the simplified model below, changing bioavailability from 50% to 100% doubles initial concentration and AUC when the other assumptions stay fixed. It does not tell us whether the new exposure is effective or tolerable.',worked:'The dose has not changed. The exposure has. Safety and activity interpretations need to account for that difference.',source:[5]},
 {id:'cmc',title:'The product people receive',group:2,goal:'Distinguish active content from purity and overall product quality.',concept:'Chemistry, manufacturing, and controls (CMC) describe the drug substance, the formulated drug product, and how their quality is controlled. Identity, active content, impurities, manufacture, and stability answer different questions. Phase 1 controls are appropriate to the development stage.',takeaway:'A favorable result for one quality attribute does not establish all the others.',exampleTitle:'99% purity. Is the capsule ready?',example:'A capsule batch has 99% chromatographic purity and an assay result of 98% of stated active content. Purity describes a measured impurity profile; assay here measures active ingredient content. The quality team reviews these results against the applicable specifications, alongside manufacturing records and stability information.',worked:'Neither number alone authorizes use. The values here are invented examples, not acceptance limits or FDA benchmarks.',source:[3]},
 {id:'clinical',title:'The first clinical study',group:2,goal:'Turn a recognized safety concern into clear study instructions.',concept:'The clinical protocol defines objectives, participants, dose and schedule, measurements, and decision rules. Its safety plan should explain what to monitor, when, who reviews the findings, and what actions follow. The specific plan depends on the drug and proposed study.',takeaway:'A concern becomes actionable when the protocol says what the team will do.',exampleTitle:'“Monitor kidney safety” needs a plan.',example:'An animal study identifies kidney injury at higher exposures. The clinical team uses this finding with the rest of the evidence to plan relevant assessments, their timing, who reviews them, and findings that trigger interruption or further evaluation. The program determines the appropriate measures.',worked:'A safety observation informs a plan that investigators can apply consistently. No single assay, threshold, or schedule is universal.',source:[4]},
 {id:'people',title:'Who prepares the IND',group:2,goal:'Distinguish contracted work from transferred sponsor obligations.',concept:'An IND is a team effort. Scientific specialists generate and interpret evidence; a regulatory lead often coordinates strategy and submission; writers and publishing specialists may help prepare the documents. The sponsor has regulatory responsibilities. Hiring a vendor does not automatically transfer them.',takeaway:'Who performs a task and who holds an obligation are different questions.',exampleTitle:'A startup works with a CRO.',example:'A biotech hires a contract research organization (CRO) for a toxicology study. Toxicology and drug metabolism/pharmacokinetics specialists interpret findings and exposure; the clinical lead considers implications for the protocol. A regulatory lead coordinates the presentation. This is one possible team arrangement. Any transfer of sponsor obligations under the IND regulation must be described in writing.',worked:'Contracting a task does not automatically transfer obligations. Those not covered by a written transfer remain with the sponsor.',source:[6]},
 {id:'review',title:'From IND to first participant',group:2,goal:'Distinguish an effective IND from trial and participant readiness.',concept:'An IND may go into effect 30 days after FDA receipt unless a clinical hold applies, or earlier on FDA notification. That is one condition for starting. Institutional review board (IRB) approval, informed consent, and applicable participant and site requirements also matter. An effective IND is not marketing approval.',takeaway:'FDA status, ethical review, and participant readiness are separate conditions.',exampleTitle:'The IND is effective. The IRB review is pending.',example:'Thirty days have elapsed since FDA received an initial IND, with no clinical hold. The IND is in effect, but the IRB has not approved the protocol. The team cannot begin this ordinary first-in-human trial while that approval is missing. The effective IND does not establish efficacy or permit marketing.',worked:'Resolve the missing IRB approval and other applicable requirements. Passage of the IND review period does not replace them.',source:[7]}
];
Object.assign(QUESTIONS,{
 cmc:{title:'Apply the distinction to another batch.',prompt:'A second batch has high chromatographic purity, but its active-content result has not been reviewed. Which conclusion is justified?',options:[['High purity establishes the intended amount in each capsule.','Purity and active content are different measurements. Review the content result against its applicable specification.',false],['The content result and other applicable quality information still need review.','A favorable purity result cannot replace the other evidence needed to assess the batch.',true],['Every animal study must be repeated before the batch can be reviewed.','That does not follow. First assess the batch and material changes; additional studies depend on the issue identified.',false]],hint:'Which measurement answers “How much active ingredient is present?”'},
 clinical:{title:'Make a vague safety plan actionable.',prompt:'A draft protocol says “watch closely for liver toxicity,” with no assessment schedule or action rules. What addresses the gap?',options:[['Specify relevant assessments, timing, review responsibilities, and justified action rules.','These instructions tell the team what to measure and how to act on the findings.',true],['Add a longer description of the target’s molecular biology.','Mechanism can inform risk, but a longer explanation does not supply the missing study instructions.',false],['Let each site invent its own monitoring plan after enrollment.','That leaves safety-critical decisions unspecified. Define the plan before conducting the study.',false]],hint:'Could two sites read that sentence and make different safety decisions?'},
 people:{title:'Who retains the responsibility?',prompt:'A biotech hires a vendor to assemble the electronic submission. No sponsor obligations are transferred in writing. Who retains those obligations?',options:[['The vendor, automatically, because it handles the files.','Performing a service does not automatically transfer sponsor obligations.',false],['FDA, once it receives the submission.','FDA reviews the application; receipt does not transfer the sponsor’s duties to FDA.',false],['The biotech sponsor.','Obligations not covered by a written transfer remain with the sponsor.',true]],hint:'Separate who did the task from which obligations were transferred.'},
 review:{title:'Check the participant’s readiness.',prompt:'The IND is effective and the IRB has approved this ordinary first-in-human study. A prospective participant has not completed informed consent. May the team give the study drug now?',options:[['Yes. IRB approval substitutes for the participant’s decision.','IRB review and individual informed consent serve different purposes. One does not replace the other.',false],['No. Legally effective informed consent is still needed before participation.','Consent is a separate prerequisite in this ordinary study. Other participant and site conditions must also be satisfied.',true],['No. Every effective IND requires another 30-day wait.','There is no automatic second 30-day wait. The missing condition here is consent.',false]],hint:'Which decision belongs to the prospective participant?'}
});
QUESTIONS.model.prompt='A separate candidate has no detected intestinal injury in a mouse study. Its tumor pathway was suppressed, but its normal intestinal pathway was not. Which conclusion is supported?';
SOURCES.push({label:'21 CFR 56.103: IRB review requirements',url:'https://www.ecfr.gov/current/title-21/chapter-I/subchapter-A/part-56/subpart-A/section-56.103'},{label:'21 CFR 50.20: informed consent',url:'https://www.ecfr.gov/current/title-21/chapter-I/subchapter-A/part-50/subpart-B/section-50.20'});
LEVELS[6].source.push(11,12);
const state={screen:'overview',lesson:'map',step:0,progress:{},loading:true,saveStatus:'',saveError:false,selected:null,feedback:false,saving:false,stream:'biology',modelEngaged:false,bioavailability:.5,halfLife:4,clipStep:0,clipPlaying:false};
let saveQueue=Promise.resolve(),clipTimer;
const ids=LEVELS.map(l=>l.id);
const level=()=>LEVELS.find(l=>l.id===state.lesson);
const done=id=>Boolean(state.progress[id]?.completed);
const countDone=()=>ids.filter(done).length;
const button=(label,action,kind='primary')=>`<button class="button ${kind}" data-action="${action}">${label}</button>`;
function announce(s){$('#announcement').textContent=s;}
function readState(){return {screen:state.screen,lesson:state.lesson,step:state.step,stepName:['Understand','See an example','Try it'][state.step],completedLevels:ids.filter(done),progressLoaded:!state.loading,saveStatus:state.saveStatus,modelEngaged:state.modelEngaged,exposure:{bioavailability:state.bioavailability,halfLife:state.halfLife,...exposureMetrics()}};}
async function request(path,body){const response=await fetch(path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let data;try{data=await response.json();}catch{throw new Error('Progress could not be reached. Your lesson is still available.');}if(!response.ok)throw new Error(data.error||'Progress could not be saved.');return data;}
function applyProgress(data){state.progress=Object.fromEntries((data.lessons||[]).filter(x=>ids.includes(x.lesson)).map(x=>[x.lesson,x]));}
async function loadProgress(){state.loading=true;try{applyProgress(await request('/api/progress'));state.saveStatus='Progress saved to your account';state.saveError=false;}catch(e){state.saveStatus=e.message;state.saveError=true;}state.loading=false;render(false);}
function updateSaveLabel(){const el=$('#save-status');if(el){el.textContent=state.saveStatus;el.classList.toggle('error',state.saveError);}}
function queueStepSave(id,step){state.saveStatus='Saving your place…';state.saveError=false;updateSaveLabel();saveQueue=saveQueue.then(async()=>{try{const data=await request('/api/progress',{lesson:id,step});applyProgress(data);state.saveStatus='Progress saved to your account';state.saveError=false;}catch(e){state.saveStatus=e.message;state.saveError=true;}updateSaveLabel();});return saveQueue;}
function resumeId(){return LEVELS.filter(l=>state.progress[l.id]&&!done(l.id)).sort((a,b)=>(state.progress[b.id].updatedAt||0)-(state.progress[a.id].updatedAt||0))[0]?.id||ids.find(id=>!done(id))||'map';}
function overview(){const current=resumeId(),index=ids.indexOf(current),completed=countDone(),started=Boolean(state.progress[current]);return `<section class="overview-intro"><p class="eyebrow">IND FOUNDATIONS</p><h1>From candidate to first human study.</h1><p>You know drug discovery. These seven levels introduce what happens next.</p></section><div class="journey" aria-label="Development overview"><span>Development<br><strong>candidate</strong></span><b aria-hidden="true">→</b><span>Evidence +<br><strong>clinical plan</strong></span><b aria-hidden="true">→</b><span>First human<br><strong>study</strong></span></div><section class="next-level"><div><p class="eyebrow">${completed===7?'FOUNDATION COMPLETED':started?'CONTINUE YOUR LEARNING':'START HERE'}</p><h2>${completed===7?'You have completed all seven exercises.':`${index+1}. ${LEVELS[index].title}`}</h2><p>${completed===7?'Revisit any level below.':'Understand → See an example → Try it'}</p></div><button class="button primary" data-level="${current}">${completed===7?'Review level 1':started?`Resume level ${index+1}`:`Start level ${index+1}`} →</button></section><div class="progress-heading"><h2>Your levels</h2><span>${completed} of 7 completed</span></div><progress value="${completed}" max="7" aria-label="Completed levels">${completed} of 7</progress><div class="level-groups">${['Get oriented','Interpret the evidence','Bring the pieces together'].map((g,i)=>`<section class="level-group"><h3>${g}</h3><div class="level-row">${LEVELS.filter(l=>l.group===i).map(l=>{const status=done(l.id)?'Completed':state.progress[l.id]?'In progress':'Not started';return `<button class="level-tile ${done(l.id)?'complete':''} ${l.id===current&&completed<7?'current':''}" data-level="${l.id}"><span class="level-icon">${done(l.id)?'✓':ids.indexOf(l.id)+1}</span><strong>${l.title}</strong><small>${status}</small></button>`;}).join('')}</div></section>`).join('')}</div><div class="overview-bottom"><p id="save-status" class="save-status ${state.saveError?'error':''}" role="status">${state.loading?'Loading saved progress…':escapeHtml(state.saveStatus)}</p>${state.saveError?button('Retry progress sync','retry','quiet'):''}<p class="fine-print">Completion records finished exercises. This is a learning sequence; real development workstreams overlap.</p><button class="text-button" data-action="curriculum">Where the course goes next ↗</button></div>`;}
function understanding(){const l=level();return `<p class="eyebrow">THE CONCEPT</p><h2>${l.title}</h2><p>${l.concept}</p>${conceptDiagram()}<div class="takeaway"><span>Keep this idea</span><strong>${l.takeaway}</strong></div>`;}
function boxes(items){return `<div class="concept-diagram">${items.map((x,i)=>`${i?'<b aria-hidden="true">→</b>':''}<div><small>${x[0]}</small><strong>${x[1]}</strong></div>`).join('')}</div>`;}
function conceptDiagram(){const diagrams={map:[['Discovery result','A reason to develop'],['IND','Support a proposed study']],model:[['Measured observation','What happened here?'],['Human inference','Does the condition transfer?']],exposure:[['Dose','Amount administered'],['Exposure','Concentration over time']],cmc:[['Drug substance','Active ingredient'],['Drug product','What people receive']],clinical:[['Safety concern','What could happen?'],['Protocol','What will the team do?']],people:[['Contracted task','Who performs the work?'],['Sponsor obligation','Who is responsible?']],review:[['IND status','May investigation proceed?'],['Trial readiness','Can this participant start?']]};return boxes(diagrams[state.lesson]);}
function example(){const l=level();return `<p class="eyebrow">WORKED EXAMPLE · INVENTED</p><h2>${l.exampleTitle}</h2><p>${l.example}</p>${state.lesson==='map'?evidenceExample():state.lesson==='model'?modelExample():state.lesson==='exposure'?exposureExample():simpleExample()}<div class="worked-answer"><span>How to reason through it</span><p>${l.worked}</p></div>`;}
function evidenceExample(){const s=STREAMS.find(x=>x.id===state.stream);return `<div class="example-board"><div class="evidence-tabs" aria-label="Explore an IND workstream">${STREAMS.map(x=>`<button data-stream="${x.id}" aria-pressed="${x.id===s.id}" class="${x.id===s.id?'active':''}">${x.name}</button>`).join('')}</div><div class="evidence-detail" aria-live="polite"><h3>${s.title}</h3><p>${s.text}</p></div></div>`;}
function modelExample(){return `<div class="example-board"><div class="model-pair"><div><span>Human tumor</span><strong>Pathway suppressed</strong><p>Growth slows</p></div><div class="${state.modelEngaged?'engaged':''}"><span>Mouse intestine</span><strong>${state.modelEngaged?'Pathway suppressed':'Pathway remains active'}</strong><p>No injury detected</p></div></div><label class="toggle"><input type="checkbox" id="model-engaged" ${state.modelEngaged?'checked':''}><span>What if the mouse intestinal pathway were also suppressed?</span></label><p class="model-result" aria-live="polite">${state.modelEngaged?'Holding the injury observation constant, the negative finding becomes more informative. Human risk still depends on exposure, duration, assessments, and biological differences.':'The mouse intestine did not experience the relevant pathway inhibition. This leaves the human on-target risk unresolved.'}</p></div>`;}
function exposureMetrics(){const f=state.bioavailability,h=state.halfLife,k=Math.log(2)/h;return {initial:100*f,auc:100*f/k,residual:100*f*Math.exp(-k*24)};}
function exposureChart(){const m=exposureMetrics(),compact=window.matchMedia('(max-width:600px)').matches,width=compact?320:580,scale=compact?10:20;const path=(f,h)=>Array.from({length:97},(_,i)=>`${i?'L':'M'}${58+i/4*scale},${215-100*f*Math.exp(-Math.log(2)/h*i/4)*1.7}`).join(' ');return `<svg viewBox="0 0 ${width} 265" role="img" aria-label="Illustrative concentration over 24 hours. Initial concentration ${m.initial.toFixed(0)} units; AUC ${m.auc.toFixed(0)} unit hours."><text x="58" y="20">${compact?'Concentration (a.u.)':'Concentration (arbitrary units)'}</text>${[0,50,100].map(v=>`<line x1="58" y1="${215-v*1.7}" x2="${58+24*scale}" y2="${215-v*1.7}"/><text x="45" y="${220-v*1.7}" text-anchor="end">${v}</text>`).join('')}<path d="${path(.5,4)}" class="baseline"/><path d="${path(state.bioavailability,state.halfLife)}" class="curve"/>${[0,12,24].map(t=>`<text x="${58+t*scale}" y="240" text-anchor="middle">${t}</text>`).join('')}<text x="${58+12*scale}" y="262" text-anchor="middle">Time (hours)</text></svg>`;}
function exposureExample(){const m=exposureMetrics();return `<div class="example-board exposure-board"><div class="chart-legend"><span>Blue: your settings</span><span>Dashed: 50%, 4 h</span></div><div id="exposure-chart">${exposureChart()}</div><div class="range-row"><label for="bioavailability">Bioavailability <output id="f-value">${Math.round(state.bioavailability*100)}%</output></label><input id="bioavailability" type="range" min="10" max="100" step="5" value="${state.bioavailability*100}"></div><div id="exposure-metrics" class="metrics" aria-live="polite"><span>Initial concentration <strong>${m.initial.toFixed(0)} units</strong></span><span>Total exposure (AUC₀–∞) <strong>${m.auc.toFixed(0)} unit·h</strong></span></div><details class="optional"><summary>Explore half-life and model assumptions</summary><div class="range-row"><label for="half-life">Elimination half-life <output id="h-value">${state.halfLife} h</output></label><input id="half-life" type="range" min="1" max="12" step="1" value="${state.halfLife}"></div><p><code>C(t) = 100 × F × exp(−ln(2) × t / t½)</code></p><p>Fixed dose-to-volume scale; instantaneous systemic entry and first-order elimination. No absorption phase, tissue distribution, metabolites, repeat dosing, or clinical thresholds. Half-life need not equal biological effect duration. AUC₀–∞ = 100 × F × t½ / ln(2).</p><button class="text-button" data-action="reset-exposure">Reset to 50% and 4 hours</button></details></div>`;}
function simpleExample(){const data={cmc:[['Purity','Measured impurity profile'],['Active content','Amount of active ingredient'],['Quality review','Relevant evidence together']],clinical:[['Finding','Kidney injury at higher exposures'],['Plan','Assessments + timing + reviewer'],['Action','Justified interruption / evaluation rules']],people:[['CRO','Performs an agreed task'],['Team','Interprets and integrates evidence'],['Sponsor','Retains obligations not transferred']],review:[['IND status','Effective ✓'],['IRB approval','Pending'],['First participant','Cannot start yet']]};return `<div class="worked-steps">${data[state.lesson].map((x,i)=>`<div><span>${i+1}</span><p><strong>${x[0]}</strong>${x[1]}</p></div>`).join('')}</div>`;}
function practice(){const q=QUESTIONS[state.lesson];const selected=Number.isInteger(state.selected)?q.options[state.selected]:null;return `<p class="eyebrow">YOUR TURN</p><h2>${q.title}</h2><p>${q.prompt}</p><fieldset class="choices"><legend class="sr-only">Choose one answer</legend>${q.options.map((o,i)=>`<label class="choice ${state.selected===i?'selected':''}"><input type="radio" name="answer" value="${i}" ${state.selected===i?'checked':''}><span class="choice-letter">${String.fromCharCode(65+i)}</span><span>${o[0]}</span></label>`).join('')}</fieldset><div id="feedback" aria-live="polite">${state.feedback&&selected?`<div class="feedback ${selected[2]?'correct':''}"><strong>${selected[2]?'That conclusion is supported.':'Revisit the reasoning.'}</strong><p>${selected[1]}</p></div>`:''}</div><details class="hint"><summary>Show a hint</summary><p>${q.hint||'Separate the measured observation from the human or safety conclusion. Which extra assumption would that conclusion need?'}</p></details>`;}
function lessonView(){const l=level(),n=ids.indexOf(l.id)+1,correct=state.feedback&&QUESTIONS[l.id].options[state.selected]?.[2];return `<div class="lesson-meta"><button class="text-button" data-action="overview">← All levels</button><span>Level ${n} of 7${done(l.id)?' · Completed ✓':''}</span></div><div class="lesson-title"><p>${l.title} · <button class="text-button" data-action="goal">Show goal</button></p></div><ol class="stepper" aria-label="Lesson steps">${['Understand','See an example','Try it'].map((label,i)=>`<li class="${state.step===i?'active':state.step>i?'passed':''}" ${state.step===i?'aria-current="step"':''}><span>${i+1}</span>${label}</li>`).join('')}</ol><section class="lesson-card">${(state.step===0?understanding():state.step===1?example():practice()).replace(/<h2>/g,"<h1>").replace(/<\/h2>/g,"</h1>")}</section><div class="lesson-controls">${state.step?button('← Back','back','quiet'):'<span></span>'}${state.step<2?button(state.step===0?'See an example →':'Your turn →','next'):correct?`<button class="button primary" data-action="complete" ${state.saving?'disabled':''}>${state.saving?'Saving…':'Complete level ✓'}</button>`:`<button class="button primary" data-action="check" ${state.selected===null?'disabled':''}>Check my answer</button>`}</div><p id="save-status" class="save-status ${state.saveError?'error':''}" role="status">${escapeHtml(state.saveStatus)}</p><details class="extra-help"><summary>Sources & optional tools</summary><div class="extra-links">${button('Sources for this level','sources','quiet')}${button('Use with AI','ai','quiet')}${state.lesson==='model'?button('Visual recap','clip','quiet')+button('Design an experiment','experiment','quiet'):''}${state.lesson==='review'?button('Inside the submission','dossier','quiet'):''}</div></details>`;}
function completionView(){const l=level(),index=ids.indexOf(l.id),next=ids[index+1];return `<section class="completion"><span class="completion-mark" aria-hidden="true">✓</span><p class="eyebrow">LEVEL ${index+1} COMPLETE</p><h1>${l.title}</h1><p>${l.takeaway}</p><span class="completion-count">${countDone()} of 7 levels completed</span><div class="completion-actions">${next?`<button class="button primary" data-level="${next}">Next: ${LEVELS[index+1].title} →</button>`:button('Return to overview','overview')}<button class="text-button" data-action="overview">See your progress</button></div></section>`;}
function render(focus=true){document.body.classList.toggle('is-overview',state.screen==='overview');$('#lesson').innerHTML=state.screen==='overview'?overview():state.screen==='complete'?completionView():lessonView();document.title=(state.screen==='overview'?'Course overview':level().title)+' · IND Evidence Lab';if(focus){$('#lesson').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}}
function showOverview(){stopClip();if($('#modal').open)$('#modal').close();state.screen='overview';history.replaceState(null,'','#overview');render();return readState();}
function startLevel(id,step){if(!ids.includes(id))throw new Error('Unknown level');if(step!==undefined&&(!Number.isInteger(step)||step<0||step>2))throw new Error('Step must be 0, 1, or 2');stopClip();if($('#modal').open)$('#modal').close();state.lesson=id;state.step=step??(done(id)?0:state.progress[id]?.step??0);state.selected=null;state.feedback=false;state.screen='lesson';history.replaceState(null,'',`#${id}/${state.step}`);render();queueStepSave(id,state.step);return readState();}
function moveStep(delta){if(state.screen!=='lesson'||![-1,1].includes(delta))return;state.step=Math.min(2,Math.max(0,state.step+delta));state.selected=null;state.feedback=false;history.replaceState(null,'',`#${state.lesson}/${state.step}`);render();queueStepSave(state.lesson,state.step);}
function checkAnswer(){if(state.selected===null)return;state.feedback=true;render(false);announce(QUESTIONS[state.lesson].options[state.selected][1]);$('#feedback').scrollIntoView({block:'nearest',behavior:'smooth'});}
async function completeLevel(){if(state.saving||state.screen!=='lesson'||state.step!==2||!state.feedback||!QUESTIONS[state.lesson].options[state.selected]?.[2])return;const lesson=state.lesson,answer=state.selected;state.saving=true;render(false);saveQueue=saveQueue.then(async()=>{try{applyProgress(await request('/api/complete',{lesson,answer}));state.saveStatus='Progress saved to your account';state.saveError=false;if(state.screen==='lesson'&&state.lesson===lesson&&state.step===2){state.screen='complete';announce('Level completed and progress saved.');}}catch(e){state.saveStatus=e.message;state.saveError=true;}state.saving=false;render();});return saveQueue;}
function updateExposure(){if(!$('#exposure-chart'))return;const m=exposureMetrics();$('#exposure-chart').innerHTML=exposureChart();$('#f-value').textContent=Math.round(state.bioavailability*100)+'%';$('#h-value').textContent=state.halfLife+' h';$('#exposure-metrics').innerHTML=`<span>Initial concentration <strong>${m.initial.toFixed(0)} units</strong></span><span>Total exposure (AUC₀–∞) <strong>${m.auc.toFixed(0)} unit·h</strong></span>`;}
function setExposure(f,h){if(typeof f!=='number'||!Number.isFinite(f)||f<.1||f>1||Math.abs(f*20-Math.round(f*20))>1e-8)throw new Error('Bioavailability must be 0.10–1.00 in 0.05 increments');if(!Number.isInteger(h)||h<1||h>12)throw new Error('Half-life must be 1–12 hours');state.bioavailability=f;state.halfLife=h;if($('#bioavailability')){$('#bioavailability').value=f*100;$('#half-life').value=h;updateExposure();}return readState();}
function setModel(value){if(typeof value!=='boolean')throw new Error('engaged must be a boolean');state.modelEngaged=value;if(state.lesson==='model'&&state.step===1)render(false);return readState();}
function modal(kicker,html){stopClip();$('#modal-kicker').textContent=kicker;$('#modal-body').innerHTML=html;const title=$('#modal-body h2');if(title)title.id='dialog-title';if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0;}
function sources(){modal('SOURCES & ASSUMPTIONS',`<h2>${level().title}</h2><ul class="source-list">${level().source.map(i=>`<li><a href="${SOURCES[i].url}" target="_blank" rel="noopener noreferrer">${SOURCES[i].label} ↗</a></li>`).join('')}</ul><p>US FDA pathway. Source check: 14 September 2026. Regulations set requirements; guidance explains agency thinking within its stated context.</p><p>The examples, XYZ1 target, and model values are invented teaching tools. They do not predict human outcomes or define universal study requirements.</p>`);}
function about(){modal('ABOUT THIS COURSE','<h2>For scientists at the handoff.</h2><p>For early R&D scientists who know biology and discovery, and want to understand how a development candidate becomes a clinical-stage drug.</p><p>The approach is mechanistic, experimental, and computational: inspect the assumptions, keep claims tied to evidence, and choose useful next experiments. AI can support this reasoning with source checking.</p><p>The learning flow takes inspiration from <a href="https://github.com/pcottle/learnGitBranching" target="_blank" rel="noopener noreferrer">Learn Git Branching</a>. Seven introductory levels form this prototype. Each has a concept, a worked example, and an exercise. Saved completion means the exercise was finished, not regulatory mastery or IND readiness.</p>');}
function curriculum(){modal('THE LONGER LEARNING PATH','<h2>Build the foundation, then go deeper.</h2><p>The seven levels cover selected introductory concepts. Future lessons will expand the following topics.</p><ol class="source-list">'+COURSE.map(c=>`<li><strong>${c[0]}</strong><br>${c[1]}</li>`).join('')+'</ol>');}
function dossier(){modal('OPTIONAL REFERENCE','<h2>Where the evidence goes.</h2><p>The electronic common technical document (eCTD) organizes material into five modules.</p><ol><li>Regional administrative material, including the US investigator’s brochure.</li><li>Summaries.</li><li>Quality / CMC.</li><li>Nonclinical study reports.</li><li>Clinical material, including protocols.</li></ol><p>An initial IND need not populate every later-stage section. Technical file acceptance is distinct from scientific review.</p><a href="'+SOURCES[8].url+'" target="_blank" rel="noopener noreferrer">FDA eCTD reference ↗</a>');}
function ai(){const prompt=`Teach me one concept at a time about US IND development. I am an early R&D scientist with experimental and computational biology experience. Current level: ${level().title}. Goal: ${level().goal}\n\nGive one concrete example, then ask one question and wait. Separate observations, inferences, and missing evidence. Verify regulatory claims against current primary FDA or ICH sources, state the scope, and distinguish requirements from guidance. Do not invent FDA decisions or universal study requirements.\n\nCurrent model settings, if relevant: bioavailability ${state.bioavailability}, half-life ${state.halfLife} h, hypothetical mouse intestinal pathway suppression ${state.modelEngaged}. Model values are illustrative and cannot select clinical doses.\n\nSources:\n${level().source.map(i=>SOURCES[i].url).join('\n')}`;modal('OPTIONAL AI PRACTICE',`<h2>Take this concept to your AI tool.</h2><p>Copy the prompt below into your preferred tool. This website does not connect to a live AI model.</p><label for="ai-prompt">Learning prompt</label><textarea id="ai-prompt" rows="9">${escapeHtml(prompt)}</textarea><div class="modal-actions">${button('Copy prompt','copy')}<span id="copy-status" role="status"></span></div>`);}
async function copyPrompt(){try{await navigator.clipboard.writeText($('#ai-prompt').value);$('#copy-status').textContent='Copied.';}catch{$('#ai-prompt').focus();$('#ai-prompt').select();$('#copy-status').textContent='Use your keyboard to copy the selected text.';}}
function experiment(){modal('OPTIONAL EXPERIMENT DESIGN',`<h2>Address the missing condition.</h2><label for="experiment-note">What model, measurements, and decision would you propose?</label><textarea id="experiment-note" rows="4">${escapeHtml(state.experimentNote||'')}</textarea><p class="fine-print">This optional draft stays in this page session; it is not sent to AI.</p><details><summary>Compare with a worked answer</summary><p>Use a justified model of normal human intestinal function where the drug engages XYZ1. Measure pathway suppression, exposure, and function or injury over time. Interpret a negative finding with assay sensitivity, duration, and model limitations.</p><p>Human intestinal organoids could contribute evidence, but one assay is not a complete safety package.</p></details>`);}
function stopClip(){clearTimeout(clipTimer);state.clipPlaying=false;}
function clip(){state.clipStep=0;modal('55-SECOND VISUAL RECAP · CAPTIONED, NO AUDIO','<h2>Watch the evidence split.</h2><div id="clip-stage"></div><div class="clip-controls">'+button('← Back','clip-prev','quiet')+'<button class="button primary" data-action="clip-play" id="clip-play">Play</button>'+button('Next →','clip-next','quiet')+'</div><details><summary>Read the transcript</summary>'+CLIP.map(c=>`<p>${c[1]}</p>`).join('')+'</details>');drawClip();}
function drawClip(){const c=CLIP[state.clipStep];$('#clip-stage').innerHTML=`<div class="clip-art"><span>${state.clipStep+1} / 6</span><strong>${c[2]}</strong><small>${c[3]}</small></div><p>${c[1]}</p>`;$('#clip-play').textContent=state.clipPlaying?'Pause':state.clipStep===5?'Replay':'Play';$('[data-action="clip-prev"]').disabled=state.clipStep===0;$('[data-action="clip-next"]').disabled=state.clipStep===5;}
function scheduleClip(){clipTimer=setTimeout(()=>{if(!state.clipPlaying)return;if(state.clipStep===5){stopClip();drawClip();return;}state.clipStep++;drawClip();scheduleClip();},CLIP[state.clipStep][4]*1000);}
function playClip(){if(state.clipPlaying){stopClip();drawClip();return;}if(state.clipStep===5)state.clipStep=0;state.clipPlaying=true;drawClip();scheduleClip();}
document.addEventListener('click',e=>{const l=e.target.closest('[data-level]');if(l){startLevel(l.dataset.level);return;}const stream=e.target.closest('[data-stream]');if(stream){state.stream=stream.dataset.stream;render(false);return;}const b=e.target.closest('[data-action]');if(!b)return;const actions={goal:()=>modal("YOUR GOAL",`<h2>${level().title}</h2><p>${level().goal}</p>`),overview:showOverview,back:()=>moveStep(-1),next:()=>moveStep(1),check:checkAnswer,complete:completeLevel,retry:loadProgress,sources,about,curriculum,dossier,ai,copy:copyPrompt,experiment,clip,'reset-exposure':()=>setExposure(.5,4),'clip-play':playClip,'clip-prev':()=>{stopClip();state.clipStep=Math.max(0,state.clipStep-1);drawClip();},'clip-next':()=>{stopClip();state.clipStep=Math.min(5,state.clipStep+1);drawClip();}};actions[b.dataset.action]?.();});
document.addEventListener('change',e=>{if(e.target.name==='answer'){state.selected=Number(e.target.value);state.feedback=false;render(false);$(`input[name="answer"][value="${state.selected}"]`).focus({preventScroll:true});}if(e.target.id==='model-engaged'){setModel(e.target.checked);$('#model-engaged').focus({preventScroll:true});}});
document.addEventListener('input',e=>{if(e.target.id==='bioavailability')setExposure(Number(e.target.value)/100,state.halfLife);if(e.target.id==='half-life')setExposure(state.bioavailability,Number(e.target.value));if(e.target.id==='experiment-note')state.experimentNote=e.target.value;});
$('#close-modal').addEventListener('click',()=>$('#modal').close());$('#modal').addEventListener('close',stopClip);
window.addEventListener('hashchange',()=>{if(location.hash==='#overview'||!location.hash)showOverview();});
window.matchMedia('(max-width:600px)').addEventListener('change',updateExposure);
async function registerAgentTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const schema=(properties,required=[])=>({type:'object',properties,required,additionalProperties:false});const validate=(input,keys)=>{if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).some(k=>!keys.includes(k)))throw new Error('Invalid tool input');};const definitions=[{name:'read_learning_state',description:'Read current level, lesson step, saved completion, and model settings.',inputSchema:schema({}),annotations:{readOnlyHint:true},execute(input){validate(input,[]);return readState();}},{name:'navigate_learning_lesson',description:'Open the overview or a level. Navigation does not complete an exercise.',inputSchema:schema({lesson:{type:'string',enum:['overview',...ids]},step:{type:'integer',minimum:0,maximum:2}},['lesson']),execute(input){validate(input,['lesson','step']);if(input.lesson==='overview')return showOverview();return startLevel(input.lesson,input.step);}},{name:'configure_model_condition',description:'Set hypothetical mouse intestinal pathway suppression and open its worked example.',inputSchema:schema({engaged:{type:'boolean'}},['engaged']),execute(input){validate(input,['engaged']);setModel(input.engaged);return startLevel('model',1);}},{name:'configure_exposure_model',description:'Configure the illustrative PK model and open its worked example. Does not select clinical doses.',inputSchema:schema({bioavailability:{type:'number',minimum:.1,maximum:1,multipleOf:.05},halfLife:{type:'integer',minimum:1,maximum:12}},['bioavailability','halfLife']),execute(input){validate(input,['bioavailability','halfLife']);setExposure(input.bioavailability,input.halfLife);return startLevel('exposure',1);}}];for(const t of definitions)try{await context.registerTool({...t,annotations:{readOnlyHint:false,untrustedContentHint:false,...t.annotations}},{signal:lifecycle.signal});}catch{console.warn('Optional learning tool unavailable.');}}
render(false);loadProgress();registerAgentTools();
